INSERT INTO changes (date, who, what, docs) VALUES ('2026-11-19', 'CashDublo', 'Updated the canonical site navigation to a stationary CashDublo wordmark in a 72px green header with full-bar menu hit area and accessible sliding drawer. Extracted reusable cashdublo-nav.js/css, with Escape/outside close, keyboard focus containment, reduced motion and responsive desktop/tablet/phone layouts.', 'assets/site-navigation.js; assets/site-navigation.css; assets/cashdublo-nav.js; assets/cashdublo-nav.css; NAVIGATION-STANDARD.md; tests/navigation-contract.test.cjs');
INSERT INTO changes (date, who, what, docs) VALUES ('2026-11-19', 'CashDublo', 'Made the reusable navigation component self-initialize after DOM readiness, while keeping initialization idempotent for the main-site loader.', 'assets/cashdublo-nav.js');
INSERT INTO changes (date, who, what, docs) VALUES ('2026-11-19', 'CashDublo', 'Made the shared navigation drawer reusable with any id named by aria-controls and allowed app-specific buttons to close the drawer via data-cd-close.', 'assets/cashdublo-nav.js; NAVIGATION-STANDARD.md');
INSERT INTO changes (date, who, what, docs) VALUES ('2026-11-20', 'Onyx (AI-01)', 'Contact email replaced site-wide on the President''s order: every CashDublo@gmail.com is now cash.dublo@gmail.com, on the root pages, the app pages, the front-end pages, and the AI version folders. Website icon added: favicon.ico, favicon-32.png, and apple-touch-icon.png at the root and in every AI folder, with the icon links in every page head so the mark loads in the address bar.', 'all pages; all AI folders');
INSERT INTO changes (date, who, what, docs) VALUES ('2026-11-20', 'ChatGPT / AI-02', 'Expanded the shared header interaction so tapping or clicking the CashDublo wordmark also toggles the navigation drawer; the full green header remains a menu hit area, with keyboard activation, focus handling, and the stationary brand preserved. The brand no longer navigates away when tapped; Home remains available in the drawer. Browser/device interaction QA remains required.', 'assets/cashdublo-nav.js; assets/cashdublo-nav.css; NAVIGATION-STANDARD.md; tests/responsive-layout.test.mjs');
INSERT INTO changes (date, who, what, docs) VALUES ('2026-11-20', 'Onyx / AI-01', 'The Front Ends page became the link hub on the President''s order: it now opens with The Doors — the live links (the CashDublo Server back end and this Showcase, each with its true state, the built App Store doors named as switching on with the server update) — and carries a new Web Apps section setting up every web app with its true state and repository link (Travel Journal Web dormant, the rest built with no live address yet). PRODUCTION-SITE-PLAN.md added: the President''s decision that production is cashdublo.com built in clean segments, this site staying the hub and workshop, the server update and new layouts being the President''s own round.', 'front-ends.html; PRODUCTION-SITE-PLAN.md');
INSERT INTO changes (date, who, what, docs) VALUES ('2026-11-20', 'Onyx / AI-01', 'The theme shelf landed in a new themes/ folder on the President''s order: the theme file standard (themes/README.md) — themes ship as compatible pairs, a .wthm for web faces and an .athm for applications, one core of the 21 color jobs in each — and the six house themes as pairs (Porcelain, Obsidian Gold, Midnight Slate, Goldbone, King, Queen), built from the theme module''s own palette records with every role filled, plus index.json listing the shelf. The hub serves the files directly, so every web face can fetch its .wthm today.', 'themes/README.md; themes/index.json; themes/porcelain.wthm; themes/porcelain.athm; themes/obsidian.wthm; themes/obsidian.athm; themes/slate.wthm; themes/slate.athm; themes/goldbone.wthm; themes/goldbone.athm; themes/king.wthm; themes/king.athm; themes/queen.wthm; themes/queen.athm');
INSERT INTO changes (date, who, what, docs) VALUES ('2026-11-20', 'Onyx / AI-01', 'PRODUCTION-SITE-PLAN.md gained the finished-server copy rule on the President''s order: when the production server is finished, a copy of its website is put in a repository called Current Production Server (hyphen form Current-Production-Server on GitHub) as the standing snapshot of the production site as it runs.', 'PRODUCTION-SITE-PLAN.md');
INSERT INTO changes (date, who, what, docs) VALUES ('2026-11-20', 'Onyx / AI-01', 'The module package is published on the website, as part of finishing the production server: api/modules.json (all 78 modules as API JSON, the same package the server carries, copied from the verified server package) and api/MODULE-DATA.md now stand on the hub at the same paths the server uses, so the website and the server answer with the same record.', 'api/modules.json; api/MODULE-DATA.md');
INSERT INTO changes (date, who, what, docs) VALUES ('2026-11-20', 'ChatGPT / AI-02', 'Website edition restructure recorded: the 17 AI website editions are gathered under all websites/ as the edition home. The obsolete root-level AI edition folder(s), the website builds/ copy, and the websites/ copies were removed in the final batched cleanup at 8fea7cb03887d27ea98c76d5fd6a4fca79363277. The choosing page now points visitors into all websites/; the README explains which website is the real one and records the cashtheblow.com production servers/ folder; and the midnight website job now follows the consolidated paths. This is a bookkeeping record of the restructure and its follow-up cleanup.', 'all websites/; double click to view all websites.html; README.md (commit befa5c13); cashtheblow.com production servers/; midnight website job; cleanup commit 8fea7cb03887d27ea98c76d5fd6a4fca79363277');
INSERT INTO changes (date, who, what, docs) VALUES ('2026-11-24', 'Engineering update', 'W6/W7 evidence correction: the website now separates the App Catalog record count (152) from the dated repository inventory count (142), and removes unsupported monetary prices and unapproved free-tier price claims from memberships and website-design pages. The course page''s unsupported annual revenue amount was removed without changing the surrounding teaching content. No checkout or commercial terms are implied; the App Catalog has no approved price values.', 'index.html; repositories.html; memberships.html; website-design.html; course.html');
INSERT INTO changes (date, who, what, docs) VALUES ('2026-11-24', 'Engineering update', 'W6 follow-up correction: replaced the stale 142 repository snapshot with the latest 146-repository fleet-sweep count recorded in the current AI2AISync handoff. Kept the 152 App Catalog record count separate and documented that repository counts vary by inventory script. The 146 figure is labeled with its November 24 source date.', 'repositories.html; CHANGES.md');
INSERT INTO changes (date, who, what, docs) VALUES
('2026-11-24', 'ChatGPT / AI-02', 'Added a separate corporate umbrella website prototype under corporate/: parent-company landing page plus four distinct business-division websites (CashDublo Digital, CashDublo Learning, CashDublo Studio, Get Cash Platform), shared responsive CSS and accessible mobile navigation, and architecture/acceptance documentation. Existing root site remains unchanged. Cash Flow is presented as a proposed umbrella brand; divisions are not represented as legally formed subsidiaries. Feature branch only; no merge or deployment.', 'corporate/index.html; corporate/digital/index.html; corporate/learning/index.html; corporate/studio/index.html; corporate/get-cash/index.html; corporate/assets/corporate.css; corporate/assets/corporate.js; corporate/ARCHITECTURE.md; corporate/README.md');
INSERT INTO changes (date, who, what, docs) VALUES
('2026-11-25', 'Onyx / AI-01', 'The website takes the theme (website queue W19, the President''s order 2026-11-25 04:06): the site generator (make_platform_pages.py) now carries the SUNLIGHT block — the themes module sunlight gradient (GRADIENTS.md) at the one house angle (135deg), stops derived from the site palette, AA checked across every stop — and injects it into every page it builds or patches; privacy takes a dark variant derived from its own palette. The standing pages were themed with the identical block: 62 pages — the generator family (index, apps, the five platform pages, privacy), the front-ends overview and its five pages, the remaining root pages on the house palette, and the 34 per-app pages under apps/. Named not-upgradable in this round: the corporate/ site (its own design system and external CSS), the per-AI folders under all websites/ (each its own design), and the retired v2 navigation assets. No page content changed: each themed page differs from its pinned predecessor only by the added block.', 'make_platform_pages.py; CHANGES.md; CHANGES.sql; index.html; apps.html; android.html; iphone.html; mac.html; windows.html; linux.html; privacy.html; front-ends.html; front-ends/; repositories.html; memberships.html; course.html; news.html; code.html; games.html; back-ends.html; website-design.html; cashdublo-app-store.html; login.html; terminal.html; rss.html; 404.html; products.html; apps/');
INSERT INTO changes (date, who, what, docs) VALUES
('2026-11-25', 'ChatGPT / GPT-6', 'Staged a bounded website-audit patch on an isolated branch: add the missing newsletter comments dialog/form, make mailto confirmation explicitly conditional on the visitor pressing Send, align remaining active contact references with the Founder-approved cash.dublo@gmail.com address, prevent duplicate shared-navigation CSS injection, and keep the newsletter popup from bypassing an active welcome/age overlay. Birthday copy, Spotify behavior, age-gate policy, pricing, catalogue claims, and generator execution remain outside this patch. Draft review only; no merge or publication is claimed.', 'news.html; site.js; assets/site-navigation.js; repositories.html; SUGGESTIONS.md; make_platform_pages.py; tests/newsletter-contract.test.cjs; .github/workflows/site-validation.yml');
INSERT INTO changes (date, who, what, docs) VALUES
('2026-11-25', 'ChatGPT / GPT-6', 'Scope correction: the missing newsletter comments dialog is now created centrally by site.js when a page has a comments opener but no comments panel. news.html was restored byte-for-byte to the main-branch version to avoid overlapping the existing open navigation PR. The final staged diff does not change news.html.', 'site.js; news.html (restored to main); tests/newsletter-contract.test.cjs');
INSERT INTO changes (date, who, what, docs) VALUES
('2026-11-25', 'ChatGPT / GPT-6', 'GitHub Actions run 45613943172: JavaScript syntax checks PASS; navigation-contract.test.cjs PASS; newsletter-contract.test.cjs PASS. The existing responsive-layout.test.mjs then FAILS on the unchanged index.html baseline because it lacks the standard green header; index.html is not part of this PR, and existing PR #11 is the navigation/header workstream. Cloudflare Pages preview check completed successfully. Overall workflow remains FAIL due to that pre-existing baseline failure; no test was removed or bypassed.', 'PR #33; .github/workflows/site-validation.yml; tests/newsletter-contract.test.cjs; tests/responsive-layout.test.mjs; index.html unchanged');
